1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, assertNotImpersonating } from "./auth";
6	// Re-exporting a const from a "use server" file is illegal (Next throws
7	// "found object"), so the choices live in a plain module.
8	import { BACKUP_INTERVAL_CHOICES } from "./backup-intervals";
9	import { prorateDowngradeCreditCents, remainingMonths, terminationRefundCents } from "./proration";
10	import { annualDiscountPct, frozenAnnualDiscountPct } from "./annual-discount";
11	import { invoiceCreateData } from "./invoices";
12	
13	/**
14	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
15	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
16	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
17	 * and respects the "one in-flight job per server" invariant.
18	 */
19	
20	async function ownedServer(serverId: string) {
21	  const user = await requireUser();
22	  const server = await db.server.findUnique({
23	    where: { id: serverId },
24	    include: { plan: true, osTemplate: true },
25	  });
26	  if (!server) throw new Error("Not found");
27	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
28	  return { user, server };
29	}
30	
31	async function hasInflightJob(serverId: string): Promise<boolean> {
32	  const pending = await db.job.count({
33	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
34	  });
35	  return pending > 0;
36	}
37	
38	// ---------- 1. Scheduled backups ----------
39	
40	/**
41	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
42	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
43	 * first backup on its next pass.
44	 */
45	export async function setBackupSchedule(
46	  serverId: string,
47	  enabled: boolean,
48	  intervalHours: number
49	): Promise<{ error?: string }> {
50	  const { user, server } = await ownedServer(serverId);
51	
52	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
53	    return { error: "Choose a valid backup interval." };
54	  }
55	
56	  await db.server.update({
57	    where: { id: server.id },
58	    data: {
59	      autoBackup: enabled,
60	      backupIntervalHours: enabled ? intervalHours : null,
61	    },
62	  });
63	  await db.auditLog.create({
64	    data: {
65	      userId: user.id,
66	      action: "server.backup_schedule",
67	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
68	    },
69	  });
70	  revalidatePath(`/dashboard/servers/${serverId}`);
71	  return {};
72	}
73	
74	// ---------- 1b. Retry a failed provision ----------
75	
76	/**
77	 * Re-enqueue provisioning for a server that failed to build (status ERROR).
78	 *
79	 * A terminal PROVISION failure strands the server in ERROR with a red banner and
80	 * no way forward; this is the customer's self-service retry. It re-uses the exact
81	 * same job/worker machinery as the original order — the provision handler keeps
82	 * any vmid already persisted on the row, so a retry resumes rather than leaking a
83	 * second VM. Ownership-checked, guarded to ERROR only, and respects the one
84	 * in-flight job invariant. Moving the row to PROVISIONING immediately makes the
85	 * detail page show the transitional "being set up" state (and auto-refresh)
86	 * rather than the stale ERROR banner while the worker picks the job up.
87	 */
88	export async function retryProvision(serverId: string): Promise<{ error?: string }> {
89	  const { user, server } = await ownedServer(serverId);
90	
91	  if (server.status !== "ERROR") {
92	    return { error: "This server isn't in a failed state." };
93	  }
94	  if (await hasInflightJob(serverId)) {
95	    return { error: "Another operation is already in progress on this server." };
96	  }
97	
98	  await db.$transaction([
99	    db.server.update({
100	      where: { id: server.id },
101	      data: { status: "PROVISIONING", provisionError: null },
102	    }),
103	    db.job.create({ data: { type: "PROVISION", serverId } }),
104	  ]);
105	  await db.auditLog.create({
106	    data: { userId: user.id, action: "server.retry_provision", detail: serverId },
107	  });
108	  revalidatePath(`/dashboard/servers/${serverId}`);
109	  return {};
110	}
111	
112	// ---------- 2. Reinstall to a different OS ----------
113	
114	/**
115	 * Switch the server to a different OS image and reinstall. This ERASES all data:
116	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
117	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
118	 */
119	export async function reinstallToOs(
120	  serverId: string,
121	  osTemplateId: string
122	): Promise<{ error?: string }> {
123	  const { user, server } = await ownedServer(serverId);
124	
125	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
126	    return { error: "Server must be running or stopped to reinstall." };
127	  }
128	
129	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
130	  if (!os?.active) return { error: "That operating system isn't available." };
131	  if (os.id === server.osTemplateId) {
132	    return { error: "This server is already running that operating system." };
133	  }
134	  if (server.plan.ramMB < os.minRamMB) {
135	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
136	  }
137	  if (server.plan.diskGB < os.minDiskGB) {
138	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
139	  }
140	
141	  if (await hasInflightJob(serverId)) {
142	    return { error: "Another operation is already in progress on this server." };
143	  }
144	
145	  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
146	  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
147	  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
148	  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
149	  // customer must delete it (which cleanly destroys just that disk) first.
150	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
151	  if (pinnedVolumes > 0) {
152	    const n = pinnedVolumes === 1 ? "volume" : `${pinnedVolumes} volumes`;
153	    return {
154	      error:
155	        `This server still has ${pinnedVolumes === 1 ? "a" : pinnedVolumes} block-storage ${n}. ` +
156	        `Detaching isn't enough — the disk stays on this server, so a reinstall would erase it too. ` +
157	        `To KEEP the data, attach the ${pinnedVolumes === 1 ? "volume" : "volumes"} to a different server first; ` +
158	        `to discard it, delete the ${pinnedVolumes === 1 ? "volume" : "volumes"} from the Volumes page. Then reinstall.`,
159	    };
160	  }
161	
162	  // Persist the target OS and enqueue the rebuild ATOMICALLY.
163	  //
164	  // The REINSTALL handler re-provisions from `Server.osTemplateId`, so the write
165	  // has to land before the job — but as two separate statements a failure between
166	  // them left the row claiming an operating system the VM is not running, with no
167	  // job to make it true. Every page, every support view and the next reinstall
168	  // would then read that row and believe it. One transaction: either the server
169	  // is recorded as the new image AND a rebuild is queued, or neither happened.
170	  await db.$transaction([
171	    db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } }),
172	    db.job.create({ data: { type: "REINSTALL", serverId } }),
173	  ]);
174	  await db.auditLog.create({
175	    data: {
176	      userId: user.id,
177	      action: "server.reinstall_os",
178	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
179	    },
180	  });
181	  revalidatePath(`/dashboard/servers/${serverId}`);
182	  return {};
183	}
184	
185	// ---------- 3. Resize-down ----------
186	
187	/**
188	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
189	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
190	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
191	 * otherwise). A prorated credit for the price difference over the remaining term
192	 * is returned to the wallet.
193	 */
194	export async function resizeServerDown(
195	  serverId: string,
196	  newPlanId: string
197	): Promise<{ error?: string }> {
198	  // Money path: this MOVES money (a prorated credit into the wallet) and it
199	  // permanently gives up capacity the customer paid for. `cancelTransferIn`
200	  // guards its credit the same way; this one did not, so an admin impersonating
201	  // a customer could downgrade their server and cash the remaining term out into
202	  // a balance the customer never asked to convert.
203	  await assertNotImpersonating();
204	  const { user, server } = await ownedServer(serverId);
205	
206	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
207	  if (!newPlan?.active) return { error: "Plan not available." };
208	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
209	  // A GAME server cannot be prorated against its base VPS plan — and THIS is the
210	  // credit path, so this is the dangerous half.
211	  //
212	  // A game tier carries BOTH a `planId` and a `gamePlanId`, and is sold at
213	  // `gamePlan.priceCents`: a FLAT all-in price, typically LOWER than the base plan
214	  // it runs on. `orderGameServer` correctly records `termPromoPercent: 0`, because
215	  // a flat price is not a discounted one. So the credit below is computed from the
216	  // BASE plan's full monthly rate for every remaining month.
217	  //
218	  // lib/proration.ts rests on exactly one invariant — a prorated credit is
219	  // strictly less than the cash actually collected for those months — and this
220	  // breaks it. A $9.99/mo flat tier on a $20.99 base plan pays out $20.99-worth
221	  // per remaining month: real wallet money the customer never paid, self-service,
222	  // repeatable.
223	  //
224	  // Until now it was blocked ONLY by the disk-monotonic guard below, because in a
225	  // catalogue where price and disk both rise there is no cheaper plan with
226	  // equal-or-larger disk. That is a coincidence of the price list, not a
227	  // protection — one cheap high-disk plan opens it. Refusing outright matches how
228	  // `renewalCharge` already treats a game plan: all-in, no add-on lines.
229	  if (server.gamePlanId) {
230	    return {
231	      error:
232	        "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
233	    };
234	  }
235	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
236	
237	  // This action is downgrades only — upgrades go through resizeServer().
238	  if (newPlan.priceCents >= server.plan.priceCents) {
239	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
240	  }
241	  // Disk can't shrink destructively; block the move rather than lose data.
242	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
243	  // both the old and the new plan and is preserved verbatim across the resize, so
244	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
245	  // does not shrink". Nothing here ever writes extraDiskGB.
246	  if (newPlan.diskGB < server.plan.diskGB) {
247	    return {
248	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
249	    };
250	  }
251	
252	  if (await hasInflightJob(serverId)) {
253	    return { error: "Another operation is already in progress on this server." };
254	  }
255	
256	  // Credit at the SAME effective rate the upgrade path charges at (term discount
257	  // plus `server.termPromoPercent`, the rate THIS term was actually sold at) over
258	  // the SAME remaining duration — every month left on `expiresAt`, uncapped,
259	  // exactly as lib/resize.ts charges for. Both directions read that one persisted
260	  // scalar off the same row, which is what makes a round trip net to zero no matter
261	  // what dates the two halves happen on. Until 2026-07-26 the rate came from
262	  // `currentPromo(now)` instead, so a customer could upgrade under the 45% Cyber
263	  // Monday basis and downgrade under the 15% Launch Sale basis and keep the spread
264	  // on every remaining month, once per promo cycle, forever.
265	  //
266	  // The old maths credited the raw LIST-price delta, so it refunded more than the
267	  // customer had ever paid (they bought at the term-discounted, promo-reduced
268	  // price). Pricing both directions through lib/proration.ts fixed the RATE, but
269	  // this line then capped the DURATION at one term while the upgrade side did not,
270	  // which broke the round trip the other way: a customer whose stacked "Renew now"
271	  // had pushed `expiresAt` 36 months out on a 12-month term paid $544.32 to
272	  // upgrade Starter -> Max and got only $181.44 back coming straight down, so the
273	  // platform pocketed $362.88 of months they had genuinely paid for. `expiresAt`
274	  // never advances without payment, so all of those months are owed back. The cap
275	  // argument has been removed from `remainingMonths` outright — the two directions
276	  // now cannot express different durations.
277	  let creditCents = 0;
278	  if (!server.isFree && server.expiresAt) {
279	    creditCents = prorateDowngradeCreditCents({
280	      fromMonthlyCents: server.plan.priceCents,
281	      toMonthlyCents: newPlan.priceCents,
282	      termMonths: server.termMonths,
283	      termPromoPercent: server.termPromoPercent,
284	      // Mirror the upgrade charge (lib/resize.ts): credit at the annual rate the server
285	      // was FROZEN at (falling back to live only for legacy rows), so the round trip
286	      // cannot mint or lose money even if the admin retunes the setting between the two
287	      // (Finding 2). Both directions read `frozenAnnualDiscountPct(server)`.
288	      annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
289	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
290	    });
291	  }
292	
293	  await db.$transaction([
294	    ...(creditCents > 0
295	      ? [
296	          db.user.update({
297	            where: { id: server.userId },
298	            data: { balanceCents: { increment: creditCents } },
299	          }),
300	          db.walletTransaction.create({
301	            data: {
302	              userId: server.userId,
303	              amountCents: creditCents,
304	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
305	            },
306	          }),
307	        ]
308	      : []),
309	    // Record the amount credited on the job so the worker's RESIZE handler can
310	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
311	    // terminally fails — the credit is committed here, before the job runs.
312	    //
313	    // DONE, not pending: `reconcileFailedJob` (worker/index.ts) reads both fields
314	    // and claws the credit back on `direction: "down"`, guarded by `debitWallet`
315	    // so it can never drive the balance negative, and idempotent on an audit row
316	    // keyed to this job id. It is called from both terminal-failure paths.
317	    //
318	    // This carried an "INTEGRATION NEEDED" note long after the integration
319	    // landed, and on 2026-07-26 an audit read the note rather than the code and
320	    // reported a live double-credit money bug that does not exist. A stale
321	    // comment claiming work is undone costs real investigation time and, worse,
322	    // invites someone to "fix" a path that is already correct.
323	    db.job.create({
324	      data: {
325	        type: "RESIZE",
326	        serverId,
327	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
328	      },
329	    }),
330	    db.auditLog.create({
331	      data: {
332	        userId: user.id,
333	        action: "server.resize_down",
334	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
335	      },
336	    }),
337	  ]);
338	
339	  revalidatePath(`/dashboard/servers/${serverId}`);
340	  return {};
341	}
