15	async function ownedServer(serverId: string) {
16	  const user = await requireUser();
17	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
18	  if (!server) throw new Error("Not found");
19	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
20	  return { user, server };
