23	async function queueJob(
24	  serverId: string,
25	  type:
26	    | "SNAPSHOT_CREATE"
27	    | "SNAPSHOT_DELETE"
28	    | "SNAPSHOT_ROLLBACK"
29	    | "BACKUP_CREATE"
30	    | "RESIZE"
31	    | "PASSWORD_RESET",
32	  payload?: Record<string, unknown>
33	): Promise<{ error?: string }> {
34	  const pending = await db.job.count({
35	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
36	  });
37	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
38	  await db.job.create({ data: { type, serverId, payload: payload as any } });
39	  return {};
