44	/**
45	 * The ONE snapshot-name normalisation, applied identically on every path.
46	 *
47	 * `worker/index.ts` snapshotOp re-applies exactly this (`[^a-zA-Z0-9_]` stripped,
48	 * 40 chars) and throws "snapshot: invalid name" on an empty result — so a name
49	 * this module accepts but the worker rejects is a job that reports QUEUED to the
50	 * customer and then dies in the worker with a message they never see. Delete and
51	 * rollback used to pass the raw argument straight through: a TypeScript parameter
52	 * type is not validation, and these are reachable with any string at all.
53	 */
54	function cleanSnapshotName(name: unknown): string {
55	  return String(name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
56	}
57	
58	const SNAPSHOT_NAME_ERROR =
59	  "Snapshot name must be 2–40 characters of letters, digits or underscores. " +
60	  "Pick the snapshot from the list on the server page rather than typing its name.";
61	
62	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
63	  const { user, server } = await ownedServer(serverId);
64	  const clean = cleanSnapshotName(name);
65	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
66	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
67	    return { error: "Server must be running or stopped." };
68	  }
69	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
70	  if (!res.error) {
71	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
72	    revalidatePath(`/dashboard/servers/${serverId}`);
73	  }
74	  return res;
75	}
