77	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
78	  const { user } = await ownedServer(serverId);
79	  const clean = cleanSnapshotName(name);
80	  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
81	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name: clean });
82	  if (!res.error) {
83	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${clean}` } });
84	    revalidatePath(`/dashboard/servers/${serverId}`);
85	  }
