89	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
90	  const { user, server } = await ownedServer(serverId);
91	  const clean = cleanSnapshotName(name);
92	  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
93	  // A rollback rewinds the VM's disk. The worker can only do that against a real
94	  // VM in a steady state — the same precondition createSnapshot already enforced.
95	  // Without it we accepted the request, said nothing, and let the job fail in the
96	  // worker while the customer believed their server was being restored.
97	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
98	    return { error: "Server must be running or stopped to roll back to a snapshot." };
99	  }
100	  const res = await queueJob(serverId, "SNAPSHOT_ROLLBACK", { name: clean });
101	  if (!res.error) {
102	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_rollback", detail: `${serverId} ${clean}` } });
103	    revalidatePath(`/dashboard/servers/${serverId}`);
104	  }
105	  return res;
106	}
