369	    throw e;
370	  }
371	
372	  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
373	  await db.auditLog.create({
374	    data: { userId: user.id, action: "server.game_subdomain_change", detail: `${serverId} -> ${sub}` },
375	  });
