65	/**
66	 * Enqueue a one-off GAME_UPDATE job. The worker SSHes the per-family update
67	 * command over the private network, so the VM must be running.
68	 */
69	export async function triggerGameUpdate(serverId: string): Promise<{ error?: string }> {
70	  const { user, server } = await ownedServer(serverId);
71	  if (!isGameServer(server)) return { error: "Updates are only available for game servers." };
72	  if (server.status !== "RUNNING") {
73	    return { error: "Server must be running to apply a game update." };
74	  }
75	  if (!server.ipAddress || !serverRootPassword(server)) {
76	    return { error: "Server is still provisioning — try again shortly." };
77	  }
78	  const idle = await ensureIdle(serverId);
79	  if (idle.error) return idle;
80	
81	  await db.job.create({ data: { type: "GAME_UPDATE", serverId } });
82	  await db.auditLog.create({
83	    data: { userId: user.id, action: "server.game_update", detail: serverId },
84	  });
85	  revalidatePath(`/dashboard/servers/${serverId}`);
86	  return {};
87	}
