832	  // go through Checkout.
833	  const { stripeConfigured } = await import("./stripe");
834	  if (stripeConfigured()) {
835	    return { error: "Please add funds with a card via the secure checkout." };
836	  }
837	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
838	  const topupIp = clientIp(await headers());
839	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
840	  if (!topupRl.ok) {
841	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
842	  }
843	  const amount = Number(formData.get("amount"));
844	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
845	    return { error: "Amount must be between $1 and $1000." };
