854	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
855	  // sets. applyCouponToTopup re-validates for this user against the real amount.
856	  const jar = await cookies();
857	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
858	  let bonusCents = 0;
859	  let couponId: string | null = null;
860	  let couponLabel = "";
