868	      // REFUSE, don't silently drop. The old code fell through and completed the
869	      // top-up with no bonus and no message, so a code that passed validation at
870	      // the preview amount but fails against the real one (a `minAmountCents`
871	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
872	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
873	      // charged at this point, so stopping is free and the customer can retry
874	      // without the code or with a larger amount.
875	      return {
876	        error:
877	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
878	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
879	      };
880	    }
881	  }
882	
883	  try {
884	    await db.$transaction(async (tx) => {
885	      // Claim the coupon FIRST, atomically. The old code did an unconditional
886	      // `coupon.update({ timesRedeemed: { increment: 1 } })` after a plain read of
887	      // the cap in the preview, so two top-ups racing for the last slot both saw
888	      // room and both incremented — the limit could be blown past by any number of
889	      // concurrent claims. Mirror `claimOrderCoupon`: a conditional `updateMany`
890	      // gated on `timesRedeemed < max` is the only thing that atomically hands out
891	      // the final slot, and the unique(coupon,user) create fails a double-claim.
892	      if (bonusCents > 0 && couponId) {
893	        const c = await tx.coupon.findUnique({ where: { id: couponId }, select: { maxRedemptions: true } });
894	        const claim = await tx.coupon.updateMany({
895	          where:
896	            c?.maxRedemptions == null
897	              ? { id: couponId, active: true }
898	              : { id: couponId, active: true, timesRedeemed: { lt: c.maxRedemptions } },
899	          data: { timesRedeemed: { increment: 1 } },
