63	async function ownedServer(serverId: string) {
64	  const user = await requireUser();
65	  const server = await db.server.findUnique({
66	    where: { id: serverId },
67	    select: {
68	      id: true,
69	      userId: true,
70	      status: true,
71	      hostname: true,
72	      label: true,
73	      rootPassword: true,
74	      rootPasswordEnc: true,
75	      sshPort: true,
76	      gameConfig: true,
77	      dedicatedIp: { select: { address: true } },
78	      osTemplate: { select: { family: true } },
79	      gamePlan: { select: { gameFamily: true } },
80	    },
81	  });
82	  if (!server) throw new Error("Not found");
83	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
84	  return { user, server };
85	}
