87	/** Resolve the game family (game plan first, then OS template) if it is a game. */
88	function resolveFamily(server: {
89	  osTemplate?: { family?: string | null } | null;
90	  gamePlan?: { gameFamily?: string | null } | null;
91	}): string | null {
92	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
93	  return isGameFamily(fam) ? fam : null;
94	}
95	
96	function requireSpec(server: Parameters<typeof resolveFamily>[0]): GameControlSpec {
97	  const family = resolveFamily(server);
98	  const spec = controlSpec(family);
99	  if (!spec) throw new Error("This server is not a supported game server.");
100	  return spec;
101	}
