103	function throttle(userId: string, op: string, max: number): string | null {
104	  const rl = checkRateLimit(`gamectl:${op}:${userId}`, { max, windowMs: 60_000 });
105	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
106	}
