108	async function lifecycleBusy(serverId: string): Promise<boolean> {
109	  const n = await db.job.count({
110	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
111	  });
112	  return n > 0;
113	}
