115	async function gameJobInflight(serverId: string): Promise<boolean> {
116	  const n = await db.job.count({
117	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: ["GAME_POWER", "GAME_BACKUP"] as any } },
118	  });
