177	export async function gamePower(serverId: string, action: string): Promise<Result> {
178	  try {
179	    const { user, server } = await ownedServer(serverId);
180	    requireSpec(server);
181	    if (!isPowerAction(action)) return { ok: false, error: "Unsupported action." };
182	    const limited = throttle(user.id, "power", 20);
183	    if (limited) return { ok: false, error: limited };
184	    if (server.status !== "RUNNING")
185	      return { ok: false, error: "The VM must be running to control the game service." };
186	    if (await lifecycleBusy(server.id))
187	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
188	    if (await gameJobInflight(server.id))
189	      return { ok: false, error: "A game control action is already in progress on this server." };
190	
191	    await db.job.create({
192	      data: { type: "GAME_POWER", serverId: server.id, payload: { action, announce: action === "restart" } },
193	    });
194	    await db.auditLog.create({
195	      data: { userId: user.id, action: "gameserver.power", detail: `${action} on ${server.hostname}` },
196	    });
197	    revalidatePath(`/dashboard/servers/${serverId}`);
198	    return { ok: true };
199	  } catch (err) {
200	    return { ok: false, error: safeError(err) };
201	  }
202	}
