264	/**
265	 * Broadcasts a chat message to everyone on the server, branded with the
266	 * server's own name instead of the connection it was sent over.
267	 *
268	 * Deliberately uses `tellraw`, not `say` — Minecraft's remote-console RCON
269	 * connection identifies itself as a sender named "Rcon", so `/say <msg>` (which
270	 * prefixes the broadcast with the ISSUING sender's name) shows up in chat as
271	 * "[Rcon] <msg>" instead of a real server identity. `tellraw` fully controls
272	 * the displayed text, sidestepping the sender-name entirely.
273	 */
274	export async function broadcastToGameServer(serverId: string, message: string): Promise<Result> {
275	  try {
276	    const { server } = await ownedServer(serverId);
277	    const clean = message.trim();
278	    if (!clean) return { ok: false, error: "Enter a message to broadcast." };
279	    if (clean.length > 250) return { ok: false, error: "Message is too long (max 250 characters)." };
280	    const senderName = server.label || server.hostname;
281	    const payload = JSON.stringify([
282	      { text: `[${senderName}] `, color: "gold", bold: true },
283	      { text: clean, color: "white" },
284	    ]);
285	    const r = await mcRcon(serverId, `tellraw @a ${payload}`, "gameserver.broadcast", clean);
286	    return r.ok ? { ok: true } : r;
287	  } catch (err) {
288	    return { ok: false, error: safeError(err) };
289	  }
290	}
