386	async function mcRcon(serverId: string, command: string, auditAction: string, auditDetail: string): Promise<{ ok: true; response: string } | { ok: false; error: string }> {
387	  const { user, server } = await ownedServer(serverId);
388	  const spec = requireSpec(server);
389	  if (spec.family !== "minecraft") return { ok: false, error: "This feature is only available for Minecraft servers." };
390	  if (spec.rcon !== "source") return { ok: false, error: "RCON is not available for this server." };
391	  const limited = throttle(user.id, "mc-mgmt", 30);
392	  if (limited) return { ok: false, error: limited };
393	  if (SANDBOX) return { ok: true, response: `(sandbox) ${command}` };
394	  if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
395	  await db.auditLog.create({ data: { userId: user.id, action: auditAction, detail: auditDetail } });
396	  const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
397	  return res.ok ? { ok: true, response: stripAnsi(res.response) } : { ok: false, error: res.error };
398	}
