536	export async function applyGameInventoryEdit(
537	  serverId: string,
538	  playerName: string,
539	  edits: { slot: string; itemId: string; count: number }[]
540	): Promise<{ ok: true; results: { slot: string; ok: boolean; error?: string }[] } | { ok: false; error: string }> {
541	  try {
542	    const v = validMcName(playerName);
543	    if (!v.ok) return v;
544	    if (!edits.length) return { ok: false, error: "No edits provided." };
545	    if (edits.length > 50) return { ok: false, error: "Too many edits at once (max 50)." };
546	    const results: { slot: string; ok: boolean; error?: string }[] = [];
547	    for (const edit of edits) {
548	      if (!/^[a-z_.0-9]+$/i.test(edit.slot)) {
549	        results.push({ slot: edit.slot, ok: false, error: "Invalid slot." });
550	        continue;
551	      }
552	      if (!/^[a-z_][a-z0-9_:]{1,80}$/.test(edit.itemId)) {
553	        results.push({ slot: edit.slot, ok: false, error: "Invalid item." });
554	        continue;
555	      }
556	      const n = Math.max(1, Math.min(64, Math.trunc(edit.count) || 1));
557	      // MUST be namespaced "minecraft:item", not bare "item" — on Paper/Purpur
558	      // servers with EssentialsX installed, the plugin registers its own
559	      // "item" command which silently swallows the bare form (it parses
560	      // "replace" as a nonexistent item id and no-ops since the RCON sender
561	      // isn't a player). The "minecraft:" prefix forces vanilla dispatch
562	      // regardless of what a plugin has registered — see the identical,
563	      // live-verified fix and root-cause note in
564	      // lib/actions-freemc-inventory.ts (free-tier equivalent).
565	      const cmd = `minecraft:item replace entity ${v.name} ${edit.slot} with ${edit.itemId} ${n}`;
566	      const r = await mcRcon(serverId, cmd, "gameserver.inventory", `${v.name} ${edit.slot} → ${edit.itemId} x${n}`);
567	      // Transport success alone doesn't mean the game accepted the command —
568	      // Minecraft reports failures (bad slot/item/offline target) as plain
569	      // response TEXT over a normally-successful RCON round trip, so check
570	      // the response body, not just the RCON transport's ok flag.
571	      if (!r.ok) {
572	        results.push({ slot: edit.slot, ok: false, error: r.error });
573	      } else if (/unknown|no entity was found|invalid|cannot|not found|expected/i.test(r.response)) {
574	        results.push({ slot: edit.slot, ok: false, error: r.response.trim() || "Command failed." });
575	      } else {
576	        results.push({ slot: edit.slot, ok: true });
577	      }
578	    }
579	    return { ok: true, results };
580	  } catch (err) { return { ok: false, error: safeError(err) }; }
581	}
