772	export async function createGameSchedule(
773	  serverId: string,
774	  hour: number,
775	  minute: number,
776	  announce: boolean,
777	  opts?: { kind?: "restart" | "command"; command?: string; intervalMinutes?: number }
778	): Promise<Result> {
779	  try {
780	    const { user, server } = await ownedServer(serverId);
781	    requireSpec(server);
782	
783	    const kind = opts?.kind ?? "restart";
784	    const command = opts?.command ?? null;
785	    const intervalMinutes = opts?.intervalMinutes ?? null;
786	
787	    // Validate based on schedule kind
788	    if (kind === "command") {
789	      if (!command) return { ok: false, error: "A command is required for command schedules." };
790	      if (!Object.keys(SCHEDULE_COMMANDS).includes(command))
791	        return { ok: false, error: `"${command}" is not an allowed scheduled command.` };
792	      if (intervalMinutes == null) return { ok: false, error: "An interval is required for command schedules." };
793	      if (!(ALLOWED_INTERVALS as readonly number[]).includes(intervalMinutes))
794	        return { ok: false, error: "Pick a valid interval." };
795	    } else {
796	      if (!validTime(hour, minute)) return { ok: false, error: "Pick a valid time (HH:MM, UTC)." };
797	    }
798	
799	    const limited = throttle(user.id, "sched", 30);
800	    if (limited) return { ok: false, error: limited };
801	    const count = await db.gameSchedule.count({ where: { serverId } });
802	    if (count >= MAX_SCHEDULES) return { ok: false, error: `You can have at most ${MAX_SCHEDULES} schedules.` };
803	
804	    const now = new Date();
805	    await db.gameSchedule.create({
806	      data: {
807	        serverId,
808	        kind,
809	        command,
810	        hour: kind === "command" ? 0 : Math.trunc(hour),
811	        minute: kind === "command" ? 0 : Math.trunc(minute),
812	        intervalMinutes,
813	        announce: kind === "restart" ? !!announce : false,
814	        enabled: true,
815	        nextRunAt: intervalMinutes
816	          ? computeNextInterval(intervalMinutes, now)
817	          : computeNextRun(Math.trunc(hour), Math.trunc(minute)),
818	      },
819	    });
820	    const detail = kind === "command"
821	      ? `cmd:${command} every ${intervalMinutes}min on ${server.hostname}`
822	      : `${hour}:${minute} on ${server.hostname}`;
823	    await db.auditLog.create({
824	      data: { userId: user.id, action: "gameserver.schedule.create", detail },
825	    });
826	    revalidatePath(`/dashboard/servers/${serverId}`);
827	    return { ok: true };
828	  } catch (err) {
829	    return { ok: false, error: safeError(err) };
830	  }
831	}
