896	import { createHash } from "node:crypto";
897	import { isGateableCommandNode, FREEMC_GATEABLE_COMMANDS } from "./freemc-command-catalog";
898	
899	const ROLE_NAME_RE = /^[a-z][a-z0-9_]{2,19}$/;
900	const RESERVED_ROLE_NAMES = new Set(["default"]);
901	
902	function offlineUuidFor(name: string): string {
903	  const hash = createHash("md5").update(`OfflinePlayer:${name}`, "utf8").digest();
904	  hash[6] = (hash[6] & 0x0f) | 0x30;
905	  hash[8] = (hash[8] & 0x3f) | 0x80;
906	  const hex = hash.toString("hex");
907	  return [hex.slice(0, 8), hex.slice(8, 12), hex.slice(12, 16), hex.slice(16, 20), hex.slice(20)].join("-");
908	}
909	
910	type ParsedLpFile = { name: string | null; uuid: string | null; permissions: string[]; parents: string[] };
911	
912	function parseLuckPermsFile(text: string): ParsedLpFile {
913	  const lines = text.split("\n").map((l) => l.replace(/\r$/, ""));
914	  let name: string | null = null;
915	  let uuid: string | null = null;
916	  const permissions: string[] = [];
917	  const parents: string[] = [];
918	  let section: "none" | "permissions" | "parents" = "none";
919	  for (let i = 0; i < lines.length; i++) {
920	    const line = lines[i];
921	    if (line === "") continue;
922	    const isTopLevelKey = /^[A-Za-z-]+:/.test(line);
923	    if (isTopLevelKey) {
924	      if (/^name:/.test(line)) name = line.slice(5).trim().replace(/^'(.*)'$/, "$1");
925	      else if (/^uuid:/.test(line)) uuid = line.slice(5).trim();
926	      section = /^permissions:\s*$/.test(line) ? "permissions" : /^parents:\s*$/.test(line) ? "parents" : "none";
927	      continue;
928	    }
929	    const negatedHead = line.match(/^-\s+(\S+):\s*$/);
930	    const bare = line.match(/^-\s+(\S+)\s*$/);
931	    if (section === "permissions") {
932	      if (negatedHead) {
933	        const next = lines[i + 1] ?? "";
934	        const valMatch = next.match(/^\s+value:\s*(true|false)\s*$/);
935	        if (valMatch) i++;
936	        if (valMatch?.[1] === "true") permissions.push(negatedHead[1]);
937	      } else if (bare) {
938	        permissions.push(bare[1]);
939	      }
940	    } else if (section === "parents" && bare) {
