1319	    return {
1320	      ok: true,
1321	      total,
1322	      sessions: sessions.map((s) => ({
1323	        id: s.id,
1324	        playerName: s.playerName,
1325	        joinedAt: s.joinedAt.toISOString(),
1326	        leftAt: s.leftAt?.toISOString() ?? null,
1327	        durationMs: s.leftAt
1328	          ? s.leftAt.getTime() - s.joinedAt.getTime()
1329	          : null,
