1337	export type PlayerStatsResult =
1338	  | {
1339	      ok: true;
1340	      uniquePlayers: number;
1341	      totalPlaytimeMs: number;
1342	      avgSessionMs: number;
1343	      currentOnline: number;
1344	      topPlayers: { name: string; totalMs: number; sessions: number }[];
1345	    }
1346	  | { ok: false; error: string };
1347	
1348	export async function getPlayerStats(serverId: string): Promise<PlayerStatsResult> {
1349	  try {
1350	    const { server } = await ownedServer(serverId);
1351	
1352	    const [allSessions, currentOnline] = await Promise.all([
1353	      db.playerSession.findMany({
1354	        where: { serverId: server.id },
1355	        select: { playerName: true, joinedAt: true, leftAt: true },
1356	      }),
1357	      db.playerSession.count({
1358	        where: { serverId: server.id, leftAt: null },
1359	      }),
1360	    ]);
1361	
1362	    const playerMap = new Map<string, { totalMs: number; sessions: number }>();
1363	    let totalPlaytimeMs = 0;
1364	    let completedSessions = 0;
1365	
1366	    for (const s of allSessions) {
1367	      const ms = s.leftAt
1368	        ? s.leftAt.getTime() - s.joinedAt.getTime()
1369	        : Date.now() - s.joinedAt.getTime();
1370	      totalPlaytimeMs += ms;
1371	      if (s.leftAt) completedSessions++;
1372	
1373	      const key = s.playerName.toLowerCase();
1374	      const existing = playerMap.get(key) ?? { totalMs: 0, sessions: 0 };
1375	      existing.totalMs += ms;
1376	      existing.sessions += 1;
1377	      playerMap.set(key, existing);
1378	    }
1379	
1380	    // Preserve original casing for display: use the first-seen casing
1381	    const nameCasing = new Map<string, string>();
1382	    for (const s of allSessions) {
1383	      const key = s.playerName.toLowerCase();
1384	      if (!nameCasing.has(key)) nameCasing.set(key, s.playerName);
1385	    }
1386	
1387	    const topPlayers = [...playerMap.entries()]
1388	      .sort((a, b) => b[1].totalMs - a[1].totalMs)
1389	      .slice(0, 10)
1390	      .map(([key, data]) => ({
1391	        name: nameCasing.get(key) ?? key,
1392	        totalMs: data.totalMs,
1393	        sessions: data.sessions,
1394	      }));
1395	
1396	    return {
1397	      ok: true,
1398	      uniquePlayers: playerMap.size,
1399	      totalPlaytimeMs,
1400	      avgSessionMs: completedSessions > 0 ? Math.round(totalPlaytimeMs / allSessions.length) : 0,
1401	      currentOnline,
1402	      topPlayers,
1403	    };
1404	  } catch (err) {
1405	    return { ok: false, error: safeError(err) };
1406	  }
1407	}
