export type FsEntryView = { name: string; isDir: boolean; size: number; modified: number };

export async function hostingListFiles(accountId: string, relPath: string): Promise<{ error?: string; entries?: FsEntryView[]; path?: string }> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const path = String(relPath ?? "").replace(/^\/+/, "");
  if (SANDBOX) return { entries: [{ name: "public_html", isDir: true, size: 0, modified: Date.now() }], path };
  const t = fsTargetFor(ctx.a);
  if (!t) return { error: "The file manager isn’t ready yet." };
  try {
    const entries = await fsList(t, path || "public_html");
    return { entries, path: path || "public_html" };
  } catch {
    return { error: "Couldn’t read that folder." };
  }
}

export async function hostingMkdir(accountId: string, relPath: string, name: string): Promise<HostingResult> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const clean = String(name ?? "").trim().replace(/[^A-Za-z0-9._-]/g, "").slice(0, 60);
  if (!clean) return { error: "Enter a folder name." };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { error: "The file manager isn’t ready yet." };
  try { await fsMkdir(t, `${relPath}/${clean}`); return { ok: true }; }
  catch { return { error: "Couldn’t create the folder." }; }
}

export async function hostingDeleteFile(accountId: string, relPath: string, isDir: boolean): Promise<HostingResult> {
  const ctx = await ownedAccountWithNode(accountId);
  if ("error" in ctx) return { error: ctx.error };
  if (SANDBOX) return { ok: true };
  const t = fsTargetFor(ctx.a);
  if (!t) return { error: "The file manager isn’t ready yet." };
  try { await fsDelete(t, relPath, isDir); return { ok: true }; }
  catch { return { error: "Couldn’t delete it." }; }
}

